import {notify} from './site-dialogs.mjs?v=1';
import {supabase,currentUser,login} from './auth-client.mjs';
import {validateSubmission} from './admin-model.mjs';
import {supportHeads} from './farm-support-assets.mjs?v=public-data2';
const $=id=>document.getElementById(id),el=(tag,text,cls)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n},picture=(path,alt,cls)=>{const n=el('img',undefined,cls);n.src=new URL(path,import.meta.url);n.alt=alt;return n};let crops=[],rows=[],busy=false,selectedCrop=0,user=null,revision=0;const revealed=new Map();let currentCycle=Math.floor(Date.now()/43200000);
async function rpc(name,args={}){const {data,error}=await supabase.rpc(name,args);if(error)throw Error(error.message);return data}
function status(text){$('farm-status').textContent=text;if($('farm-submit-dialog').open)$('submit-status').textContent=text}
function filters(){const all=el('button','All fruits');all.type='button';all.setAttribute('aria-pressed',String(selectedCrop===0));all.onclick=()=>{selectedCrop=0;filters();render()};$('fruit-filters').replaceChildren(all,...crops.map(c=>{const b=el('button');b.type='button';b.title=c.name;b.setAttribute('aria-label',c.name);b.setAttribute('aria-pressed',String(selectedCrop===c.id));b.append(picture(c.icon,'',''));b.onclick=()=>{selectedCrop=c.id;filters();render()};return b}))}
function render(){const shown=rows.filter(r=>(!selectedCrop||r.crop_id===selectedCrop)&&Number(r.exhausted)<3);$('farm-list').replaceChildren(...shown.map(r=>{const crop=crops.find(c=>c.id===r.crop_id),card=el('article',undefined,'farm-row');card.setAttribute('aria-label',crop.support+' · '+crop.name+' · +'+r.bonus+'%');card.append(picture('./tatari-data/'+supportHeads[crop.support],crop.support,'farm-head'),picture(crop.icon,crop.name,'farm-fruit'),el('strong','+'+r.bonus+'%','farm-value'));const feedback=el('div',undefined,'farm-feedback');for(const [label,value,count] of [['Working','worked',r.worked],['Not Working','not_working',r.not_working],['Exhausted','exhausted',r.exhausted]]){const b=el('button',label+' '+Number(count||0),'btn secondary');b.type='button';b.disabled=!revealed.has(r.id);b.title=b.disabled?'Copy UID before leaving feedback':label;b.onclick=async()=>{b.disabled=true;try{await rpc('report_farm_support',{p_id:r.id,p_report:value});await reload();status('Feedback saved for this 12-hour round.')}catch(e){status(e.message);b.disabled=false}};feedback.append(b)}const connect=el('button','Copy UID','btn farm-connect');connect.type='button';connect.onclick=async()=>{connect.disabled=true;try{const uid=await rpc('reveal_farm_support',{p_id:r.id});revealed.set(r.id,uid);await reload();try{await navigator.clipboard.writeText(uid);status('UID copied. Use it in Cozy Farm to connect.');notify('UID copied')}catch{status('UID revealed on the card. Select it to copy.')}}catch(e){status(e.message)}finally{connect.disabled=false}};const uid=el('p',revealed.has(r.id)?'UID '+revealed.get(r.id):'', 'revealed');card.append(uid,feedback,connect);return card}));if(!shown.length)$('farm-list').append(el('p','No reviewed support is available for this fruit yet.','farm-empty'))}
async function reload(){const cycle=Math.floor(Date.now()/43200000);if(cycle!==currentCycle){currentCycle=cycle;revealed.clear()}rows=await rpc('farm_support_directory');const ids=new Set(rows.map(r=>r.id));for(const id of revealed.keys())if(!ids.has(id))revealed.delete(id);render();}
async function gate(){const token=++revision;user=await currentUser();if(token!==revision)return;$('farm-tools').hidden=!user;$('farm-gate').hidden=!!user;revealed.clear();if(user)try{await reload();status('Select a fruit to find support.')}catch(e){status('Could not load the support directory. '+e.message)}else status('Sign in to use the support directory.')}
function paintCrop(){const c=crops.find(c=>c.id===Number($('submit-crop').value))||crops[0];if(!c)return;$('submit-crop-icon').src=new URL(c.icon,import.meta.url);$('submit-crop-name').textContent=c.name;$('submit-crop-options').querySelectorAll('button').forEach(b=>b.setAttribute('aria-selected',String(Number(b.dataset.crop)===c.id)))}
function closeCrop(){ $('submit-crop-options').hidden=true;$('submit-crop-button').setAttribute('aria-expanded','false')}
function cropPicker(){const holder=$('submit-crop-options');holder.replaceChildren(...crops.map(c=>{const b=el('button');b.type='button';b.setAttribute('role','option');b.dataset.crop=c.id;b.append(picture(c.icon,''),el('span',c.name));b.onclick=()=>{$('submit-crop').value=c.id;paintCrop();closeCrop();$('submit-crop-button').focus()};b.onkeydown=e=>{const options=[...holder.children],i=options.indexOf(b);if(e.key==='Escape'){e.preventDefault();closeCrop();$('submit-crop-button').focus()}else if(['ArrowDown','ArrowUp','Home','End'].includes(e.key)){e.preventDefault();options[e.key==='Home'?0:e.key==='End'?options.length-1:(i+(e.key==='ArrowDown'?1:-1)+options.length)%options.length].focus()}};return b}));paintCrop()}
$('submit-crop-button').onclick=()=>{const open=$('submit-crop-options').hidden;$('submit-crop-options').hidden=!open;$('submit-crop-button').setAttribute('aria-expanded',String(open));if(open)$('submit-crop-options').querySelector('[aria-selected=true]')?.focus()};$('submit-crop-button').onkeydown=e=>{if(e.key==='ArrowDown'){e.preventDefault();$('submit-crop-options').hidden=false;$('submit-crop-button').setAttribute('aria-expanded','true');$('submit-crop-options').querySelector('[aria-selected=true]')?.focus()}};document.addEventListener('click',e=>{if(!e.target.closest('.farm-crop-picker'))closeCrop()});$('farm-submit-dialog').addEventListener('close',closeCrop);$('submit-bonus').oninput=()=>{const input=$('submit-bonus');if(input.value==='')return;const value=Number(input.value);if(value>263)input.value='263';else if(value<0)input.value='0'};
$('farm-login').onclick=()=>login('discord').catch(e=>status(e.message));$('open-submit').onclick=()=>{if(!user){status('Sign in before submitting a UID.');$('farm-login').focus();return}if(selectedCrop)$('submit-crop').value=selectedCrop;paintCrop();$('submit-status').textContent='Submissions are reviewed before appearing publicly.';$('farm-submit-dialog').showModal()};$('close-submit').onclick=()=>$('farm-submit-dialog').close();
$('farm-submit').onsubmit=async e=>{e.preventDefault();if(busy)return;try{const v=validateSubmission({uid:$('submit-uid').value.trim(),crop:Number($('submit-crop').value),bonus:Number($('submit-bonus').value),permission:$('submit-permission').checked,note:$('submit-note').value});busy=true;$('submit-button').disabled=true;await rpc('submit_farm_support',{p_uid:v.uid,p_crop:v.crop,p_bonus:v.bonus,p_permission:v.permission,p_note:v.note});$('farm-submit').reset();paintCrop();await reload();status('Submitted for review. It is not public yet.')}catch(e){status(e.message)}finally{busy=false;$('submit-button').disabled=false}};
try{const response=await fetch(new URL('./guide-data/cozy-farm.json',import.meta.url));if(!response.ok)throw Error('Fruit data unavailable');crops=(await response.json()).crops;$('submit-crop').replaceChildren(...crops.map(c=>{const n=el('option',c.name);n.value=c.id;return n}));cropPicker();filters();await gate()}catch(e){status(e.message)}supabase.auth.onAuthStateChange(()=>setTimeout(()=>gate().catch(e=>status(e.message)),0));
